(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.017-t*0.28)*16+Math.sin(x*0.015+t*0.33)*11;
  const w2x = Math.sin((x+w1x)*0.025-t*0.5)*8+Math.cos((y+w1y)*0.02+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.023+t*0.45)*9+Math.sin((x+w1x)*0.019-t*0.35)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.65+3)*70,40+Math.cos(t*0.75)*60,0.11,2.1],
    [400+Math.cos(t*0.45+2)*85,220+Math.sin(t*0.85+1)*55,0.085,1.8]
  ];
  let aS=0,iS=0,wS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.exp(-d*0.003);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    wS+=Math.sin(d*f*1.3-t*sp*0.8+3.0)*w*0.5;
  }
  const act=aS/8,inh=iS/8,wav=wS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.08+ang*2-t*2.1))*0.3;
  const voroX=Math.floor(sx/35),voroY=Math.floor(sy/35);
  let mD=99;
  for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){
    const nx=voroX+dx,ny=voroY+dy;
    const px=nx*35+Math.sin(nx*1.7+ny*2.3+t*0.6)*14+Math.cos(nx*3.1-ny*1.1+t*0.4)*10;
    const py=ny*35+Math.cos(nx*2.1+ny*1.7+t*0.5)*13+Math.sin(nx*1.3-ny*2.7+t*0.7)*9;
    const vd=Math.sqrt((sx-px)**2+(sy-py)**2);
    if(vd<mD)mD=vd;
  }
  const voroCell=Math.tanh((mD-12)*0.3)*0.6;
  const feed=act-inh*0.7+bg*0.25+spiral+wav*0.15+voroCell;
  const reaction=Math.tanh(feed*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=(Math.sin(sx*0.4+t*3)*Math.sin(sy*0.4-t*2.5)+Math.sin((sx-sy)*0.3+t*1.8))*0.15;
  const blend=reaction*0.6+cell*0.2+micro*0.2,v=blend*0.5+0.5;
  const pal=[[5,12,45],[12,45,82],[18,88,112],[25,138,135],[60,172,125],[160,195,80],[210,185,55],[215,135,65],[185,75,60],[120,35,55],[55,18,48],[5,12,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.72?1.18:Math.abs(reaction)>0.5?1.08:1.0;
  const glow=Math.max(0,reaction-0.5)*0.3;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*25)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*15)|0)
  ];
}
